SELECT
	self_delivery_operator_id AS selfDeliveryOperatorId,
	COUNT(DISTINCT user_id) AS userCount,
	COUNT(order_id) AS orderCount,
	SUM(total_fee) AS totalFeeCount,
	SUM(self_delivery_fee) AS selfDeliveryFeeCount
FROM orders_normal_orders
WHERE self_delivery_status = 'DONE'
	AND company_id = #{companyId}
	AND self_delivery_end_time >= #{startEpoch}
	AND self_delivery_end_time <= #{endEpoch}

	AND self_delivery_operator_id IN

		#{oid}



	AND distributor_id IN

		#{did}



	AND merchant_id = #{merchantId}

GROUP BY self_delivery_operator_id

SELECT
	COALESCE(SUM(CAST(total_fee AS DECIMAL(20, 2))), 0) AS payAmount,
	COUNT(DISTINCT user_id) AS payNum
FROM orders_normal_orders
WHERE company_id = #{companyId}
	AND monitor_id = #{monitorId}
	AND source_id = #{sourceId}
	AND create_time >= #{startEpoch}
	AND create_time <= #{endEpoch}
	AND pay_status = 'PAYED'

