		AND mi.mobile = #{filter.promoter_mobile})


	AND EXISTS (
		SELECT 1 FROM popularize_promoter pp
		INNER JOIN popularize_promoter_identity pid ON pid.id = pp.identity_id AND pid.company_id = pp.company_id
		WHERE pp.company_id = o.company_id AND pp.user_id = o.user_id AND pp.is_promoter = 1
		AND pid.name LIKE CONCAT('%', #{filter.promoter_identity}, '%'))

