SELECT o.*
FROM orders_normal_orders o
WHERE o.order_auto_close_aftersales_time < #{timeSec}
  AND o.order_status = 'DONE'
  AND o.is_consumption = 0

	AND o.order_id NOT IN

		#{eid}


ORDER BY o.create_time DESC
LIMIT #{limit}

